import{_ as t,o as e,c as o,y as a}from"./chunks/framework.CNTkXYA8.js";const T=JSON.parse('{"title":"【NOIP2018】为什么这么无力啊","description":"","frontmatter":{"title":"【NOIP2018】为什么这么无力啊","date":"2018-11-10T15:14:00.000Z"},"headers":[],"relativePath":"blog/noip2018.md","filePath":"source/old_posts/noip2018.md"}'),_={name:"blog/noip2018.md"};function n(r,p,s,i,c,d){return e(),o("div",null,[...p[0]||(p[0]=[a("<p>菜鸡又要爆零了</p><p>辛辛苦苦背板子结果考时候脑子一片空白</p><p>第一题线段树调了半小时</p><p>看完三道题两道写暴搜一道写暴力（说是暴搜，觉得更像写了个背包）</p><p>别提暴搜还忘记剪枝. . . . . .</p><p>我觉得考场上最菜的就是我了</p><p>周围都是大佬打键盘，只有我还在苦苦思索</p><p>带了一瓶咖啡喝掉一半还是很困</p><p>昨天晚上10：14睡觉还不早么</p><p>第一题居然是2013提高组题目</p><p>据说三道题都有原题</p><p>感觉错过了一个亿</p><p>啊啊啊发现我T1暴力写错了！！有可能样例能过错误暴力。。</p><p>我不确定是不是真的写错了，反正大概率爆炸了，，</p><p>绝望</p><p>还好我觉得T2打的正解，排序+搜索+背包。。</p><p>T3暴力暴力</p><p>DAY2</p><p>完了。。一进考场炸了，凭感觉写了玄学T1，感觉应该是分块之类的东西，明明有思路，偏偏写不出来，只好玄学爆搜</p><p>T2凭感觉（又是）找找规律，缘分这种东西总是很奇妙的</p><p>T3据说非常难。。。但是考试最后5分钟才发现有链的数据，唉。。</p><p>总结</p><p>NOIP2018——美食(并不)/划水/爆零/失去希望之旅</p><p>当做一次经历好了，这样错误下一次就不会犯了吧...题还是会越来越难吧</p><p>还是好好学习吧</p><p>——NOIP2018有感</p>",26)])])}const m=t(_,[["render",n]]);export{T as __pageData,m as default};
